package br.com.sistemacardapio.complemento;import java.util.UUID;import br.com.sistemacardapio.empresa.Empresa;import jakarta.persistence.*;
@Entity@Table(name="grupo_complemento")public class GrupoComplemento{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="empresa_id")private Empresa empresa;@Column(nullable=false,length=120)private String nome;@Column(nullable=false)private boolean obrigatorio;@Column(name="quantidade_minima",nullable=false)private int minimo;@Column(name="quantidade_maxima",nullable=false)private int maximo;@Column(nullable=false)private boolean ativo;protected GrupoComplemento(){}public GrupoComplemento(Empresa e,String n,boolean o,int min,int max){id=UUID.randomUUID();empresa=e;atualizar(n,o,min,max,true);}public void atualizar(String n,boolean o,int min,int max,boolean a){nome=n.trim();obrigatorio=o;minimo=min;maximo=max;ativo=a;}public UUID getId(){return id;}public String getNome(){return nome;}public boolean isObrigatorio(){return obrigatorio;}public int getMinimo(){return minimo;}public int getMaximo(){return maximo;}public boolean isAtivo(){return ativo;}public Empresa getEmpresa(){return empresa;}}
